//! Edge-case integration tests for marks-rendering — generated by bug-hunter agent.
//!
//! NOTE: ferrum-core's mark build functions are `pub(crate)` and can only be
//! exercised via the extensive inline unit tests inside each marks/*.rs module.
//! These integration tests focus on:
//!   - Scene-graph type contracts (via ferrum-scene public types)
//!   - Numeric correctness of path geometry math that the marks renderer relies on
//!   - Boundary values for Color, PathCmd, SceneNode construction
//!   - NaN / Inf safety of derived geometry

#[cfg(test)]
mod tests {
    use ferrum_scene::{Color, FillStroke, PathCmd};

    // ── Color boundary values ────────────────────────────────────────────

    #[test]
    fn color_rgb_sets_alpha_to_255() {
        let c = Color::rgb(100, 150, 200);
        assert_eq!(c.a, 255, "Color::rgb must set alpha to 255, got {}", c.a);
    }

    #[test]
    fn color_rgba_preserves_all_channels() {
        let c = Color::rgba(10, 20, 30, 128);
        assert_eq!(c.r, 10);
        assert_eq!(c.g, 20);
        assert_eq!(c.b, 30);
        assert_eq!(c.a, 128);
    }

    #[test]
    fn color_max_values_no_overflow() {
        let c = Color::rgba(255, 255, 255, 255);
        assert_eq!(c.r, 255);
        assert_eq!(c.a, 255);
    }

    #[test]
    fn color_min_values_no_underflow() {
        let c = Color::rgba(0, 0, 0, 0);
        assert_eq!(c.r, 0);
        assert_eq!(c.a, 0);
    }

    // ── PathCmd construction and sequence contracts ──────────────────────

    #[test]
    fn path_cmd_move_to_then_line_to_forms_valid_segment() {
        let cmds = vec![
            PathCmd::MoveTo { x: 0.0, y: 0.0 },
            PathCmd::LineTo { x: 100.0, y: 50.0 },
            PathCmd::Close,
        ];
        assert!(matches!(cmds[0], PathCmd::MoveTo { .. }),
            "first command must be MoveTo");
        assert!(matches!(cmds.last(), Some(PathCmd::Close)),
            "last command must be Close for closed paths");
    }

    #[test]
    fn path_cmd_close_is_distinct_from_line_to() {
        // Closed area marks must use PathCmd::Close, not a manual LineTo back to start.
        let close = PathCmd::Close;
        assert!(matches!(close, PathCmd::Close));
        // Verify Close and LineTo are distinct (type-level check via exhaustive match).
        let line = PathCmd::LineTo { x: 0.0, y: 0.0 };
        assert!(!matches!(line, PathCmd::Close));
    }

    #[test]
    fn path_cmd_hline_and_vline_exist_for_step_interpolation() {
        // Step interpolation uses HLineTo + VLineTo. Both variants must exist.
        let h = PathCmd::HLineTo { x: 50.0 };
        let v = PathCmd::VLineTo { y: 30.0 };
        assert!(matches!(h, PathCmd::HLineTo { x } if (x - 50.0).abs() < f64::EPSILON));
        assert!(matches!(v, PathCmd::VLineTo { y } if (y - 30.0).abs() < f64::EPSILON));
    }

    // ── SceneNode geometry invariants ───────────────────────────────────

    #[test]
    fn scene_node_circle_radius_must_be_positive() {
        // Radius derived from area = π r². For area=100, r ≈ 5.64. Must be > 0.
        let area = 100.0_f64;
        let r = (area / std::f64::consts::PI).sqrt();
        assert!(r > 0.0, "radius from area must be positive, got {r}");
        assert!(r.is_finite(), "radius from area must be finite, got {r}");
    }

    #[test]
    fn scene_node_circle_zero_area_produces_non_negative_radius() {
        // area = 0 → r = 0. Renderer uses default radius for missing size values.
        let area = 0.0_f64;
        let r = (area / std::f64::consts::PI).sqrt();
        assert!(r >= 0.0 && r.is_finite());
    }

    #[test]
    fn scene_node_rect_width_height_non_negative_from_absolute_difference() {
        // Bar width is computed as (baseline_y - top_y).max(0.0). Test the boundary.
        let baseline_y = 100.0_f64;
        let top_y = 100.0_f64; // height should be 0 when bar value == baseline
        let height = (baseline_y - top_y).max(0.0);
        assert_eq!(height, 0.0, "zero-value bar must have height 0");
        assert!(!height.is_nan());
    }

    #[test]
    fn bar_rect_negative_height_clamped_to_zero() {
        // When top_y > baseline_y (e.g., negative values on a bar chart anchored
        // to y=0), the height must not go negative.
        let baseline_y = 100.0_f64;
        let top_y = 120.0_f64; // bar tip is below the baseline in pixel space
        let height = (baseline_y - top_y).max(0.0);
        assert_eq!(height, 0.0, "bar below baseline must have clamped height 0");
    }

    // ── Diamond/Triangle path geometry numeric correctness ───────────────

    #[test]
    fn diamond_path_has_four_corners_plus_close() {
        // Diamond shape: M top, L right, L bottom, L left, Z.
        let cx = 50.0_f64;
        let cy = 50.0_f64;
        let r = 5.0_f64;
        let d = r * 1.4;
        let cmds = vec![
            PathCmd::MoveTo { x: cx, y: cy - d },
            PathCmd::LineTo { x: cx + d, y: cy },
            PathCmd::LineTo { x: cx, y: cy + d },
            PathCmd::LineTo { x: cx - d, y: cy },
            PathCmd::Close,
        ];
        assert_eq!(cmds.len(), 5, "diamond needs M + 3L + Z = 5 commands");
        // All LineTo x coordinates must be finite.
        for cmd in &cmds {
            if let PathCmd::LineTo { x, y } = cmd {
                assert!(x.is_finite() && y.is_finite(),
                    "diamond LineTo must have finite coords, got ({x}, {y})");
            }
        }
    }

    #[test]
    fn triangle_up_path_has_three_vertices_plus_close() {
        let cx = 50.0_f64;
        let cy = 50.0_f64;
        let r = 5.0_f64;
        let h = r * 1.4;
        let cmds = vec![
            PathCmd::MoveTo { x: cx, y: cy - h },
            PathCmd::LineTo { x: cx + h * 0.866, y: cy + h * 0.5 },
            PathCmd::LineTo { x: cx - h * 0.866, y: cy + h * 0.5 },
            PathCmd::Close,
        ];
        assert_eq!(cmds.len(), 4, "triangle_up: M + 2L + Z = 4 commands");
        // Symmetry: left and right base x-coords must be symmetric about cx.
        if let (PathCmd::LineTo { x: x1, .. }, PathCmd::LineTo { x: x2, .. }) = (&cmds[1], &cmds[2]) {
            let left_offset = (cx - x2).abs();
            let right_offset = (x1 - cx).abs();
            assert!((left_offset - right_offset).abs() < 1e-10,
                "triangle_up base must be symmetric: left={left_offset}, right={right_offset}");
        }
    }

    #[test]
    fn triangle_down_vertices_are_below_apex() {
        // TriangleDown: apex at bottom (cy + h), two vertices above.
        let cy = 50.0_f64;
        let r = 5.0_f64;
        let h = r * 1.4;
        let apex_y = cy + h;
        let base_y = cy - h * 0.5;
        // Apex (lowest point) must have higher y than the base in screen coords.
        assert!(apex_y > base_y,
            "TriangleDown apex y({apex_y}) must be below base y({base_y}) in screen coords");
    }

    // ── Ribbon geometry contract ─────────────────────────────────────────

    #[test]
    fn ribbon_path_top_then_bottom_reversed_then_close() {
        // Ribbon: top edge x-ascending, bottom edge x-descending, Close.
        // 3 top points → M + 2L; 3 bottom reversed → 3L; Close = 7 total.
        let points = vec![(0.0_f64, 10.0_f64, 5.0_f64),
                          (50.0, 8.0, 4.0),
                          (100.0, 6.0, 3.0)];
        let mut cmds: Vec<PathCmd> = Vec::new();
        let (x0, y0, _) = points[0];
        cmds.push(PathCmd::MoveTo { x: x0, y: y0 });
        for &(x, y, _) in &points[1..] {
            cmds.push(PathCmd::LineTo { x, y });
        }
        for &(x, _, y2) in points.iter().rev() {
            cmds.push(PathCmd::LineTo { x, y: y2 });
        }
        cmds.push(PathCmd::Close);

        assert_eq!(cmds.len(), 7, "ribbon with 3 points: M + 2L + 3L + Z = 7");
        assert!(matches!(cmds.first(), Some(PathCmd::MoveTo { .. })));
        assert!(matches!(cmds.last(), Some(PathCmd::Close)));

        // Verify no NaN in any coordinate.
        for cmd in &cmds {
            match cmd {
                PathCmd::MoveTo { x, y } | PathCmd::LineTo { x, y } => {
                    assert!(x.is_finite() && y.is_finite(),
                        "ribbon path coords must be finite: ({x}, {y})");
                }
                _ => {}
            }
        }
    }

    // ── FillStroke invariants ────────────────────────────────────────────

    #[test]
    fn fill_stroke_no_fill_is_hollow_point() {
        // Hollow points (filled=false) set fill=None and stroke=Some(color).
        let style = FillStroke {
            fill: None,
            stroke: Some(Color::rgb(50, 50, 50)),
            stroke_width: 1.5,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        assert!(style.fill.is_none(), "hollow point must have no fill");
        assert!(style.stroke.is_some(), "hollow point must have stroke color");
        assert!(style.stroke_width > 0.0, "hollow point stroke width must be positive");
    }

    #[test]
    fn fill_stroke_opacity_in_range() {
        // Opacity for any mark style must be in [0.0, 1.0].
        let test_opacities = [0.0_f64, 0.5, 1.0];
        for op in test_opacities {
            let style = FillStroke {
                fill: Some(Color::rgb(100, 100, 100)),
                stroke: None,
                stroke_width: 0.0,
                opacity: op,
                stroke_dash: None,
                stroke_opacity: 1.0,
                fill_opacity: 1.0,
                angle: 0.0,
            };
            assert!(style.opacity >= 0.0 && style.opacity <= 1.0,
                "opacity must be in [0,1], got {}", style.opacity);
        }
    }
}
